import java.util.HashSet;
import java.util.Set;
import java.util.jar.JarEntry;
import java.util.jar.JarFile;

public class TallyGate {
    public static int tint_span(Path exploded, Path names, Path jar) throws Exception {
        if (!Files.isRegularFile(jar)) {
            return 1;
        }
        Set<String> entries = new HashSet<String>();
        try (JarFile jf = new JarFile(jar.toFile())) {
            for (JarEntry e : java.util.Collections.list(jf.entries())) {
                entries.add(e.getName());
            }
        }
        for (String line : Files.readAllLines(names)) {
            String text = line.trim();
            if (text.isEmpty()) {
                continue;
            }
            String[] fields = text.split("\\s+");
            if (fields.length < 2 || !entries.contains(fields[1] + ".class")) {
                return 1;
            }
        }
        return 0;
    }

    public static void main(String[] args) throws Exception {
        System.exit(tint_span(Paths.get("/app/blastcp"),
            Paths.get("/app/desknote/NAMES.txt"),
            Paths.get("/app/jarwell/husk.jar")));
